result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    successful_transactions=COUNT(transactions_made.WHERE(LOWER(status) == 'success')),
    total_transactions=COUNT(transactions_made)
).CALCULATE(
    customer_name=customer_name,
    success_rate=100.0 * successful_transactions / total_transactions
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
).PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

top_bought_tickers = Transactions.WHERE(
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & (LOWER(transaction_type) == 'buy')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

recent_customers_by_month = Customers.WHERE(
    (DATEDIFF("months", join_date, DATETIME('now')) > 0) & (DATEDIFF("months", join_date, DATETIME('now')) <= 6)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
)

result = recent_customers_by_month.PARTITION(name="monthly_groups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
).ORDER_BY(signup_month.ASC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

price_change_by_stock = DailyPrices.WHERE(
    (date >= '2023-04-01') & (date <= '2023-04-04')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="stocks", by=(ticker_symbol,)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    price_change=MAX(DailyPrices.high) - MIN(DailyPrices.low)
)

top_stocks_by_price_change = price_change_by_stock.TOP_K(3, by=price_change.DESC())

top_customer_by_transactions_in_join_month = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_transactions=COUNT(
        transactions_made.WHERE(
            (YEAR(date_time) == YEAR(join_date)) & (MONTH(date_time) == MONTH(join_date))
        )
    )
).TOP_K(
    1,
    by=num_transactions.DESC()
).CALCULATE(
    _id=customer_id,
    name=customer_name,
    number_of_transactions=num_transactions
)

result = Customers.WHERE(
    HAS(transactions_made.WHERE(LOWER(transaction_type) == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

distinct_customer_ids = Transactions.WHERE(LOWER(transaction_type) == 'buy').PARTITION(
    name="distinct_customers", 
    by=(customer_id)
).CALCULATE(
    customer_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(
    name="tickers", 
    by=ticker_id
).CALCULATE(
    ticker_id=ticker_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

result = Tickers.WHERE(
    HASNOT(historical_prices) == 1
).CALCULATE(
    ticker_id=_id,
    symbol=symbol
)

top_countries_by_amount = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=(country_name)
).CALCULATE(
    country=country_name,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(
    5, by=total_transaction_amount.DESC()
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

recent_customers = Customers.WHERE(
    DATEDIFF("days", join_date, DATETIME("now")) <= 70
)
result = Broker.CALCULATE(
    total_transactions=COUNT(recent_customers.transactions_made)
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400.0
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (LOWER(transaction_type) == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

top_customer_by_transactions = Customers.CALCULATE(
    _id,
    name,
    num_transactions=COUNT(transactions_made.WHERE(
        (LOWER(transaction_type) == 'sell') & 
        (DATEDIFF("days", date_time, "2023-04-01") == 0)
    ))
).WHERE(
    num_transactions > 0
).TOP_K(
    1, 
    by=num_transactions.DESC()
)

sales_by_model = Dealership.Cars.WHERE(
    LIKE(LOWER(vin_number), '%m5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    number_of_sales=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        )
    ),
    total_revenue=SUM(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    asp_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            ISIN(MONTH(sale_date), (1, 2, 3))
        ).sale_price
    )
)

asp_q1_2023 = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_between_sale_and_payment = ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff = DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

highest_priced_car = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (is_in_inventory == False) & (snapshot_date == sale_date)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Dealership.CALCULATE(
    total_sales_count=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') <= 7))
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') <= 7))
)

result = Customers.WHERE(
    HAS(car_purchases) == 1
).CALCULATE(
    customer_id=_id
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

result = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == LOWER("cash"))) == 1
).CALCULATE(
    salesperson_id=_id
)

salesperson_ids_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == LOWER('Utility Company')) &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

weekend_payments_to_utility_co = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

inventory_cars = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1
).WHERE(
    is_in_inventory == True
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

result = DermTreatment.CALCULATE(
    num_patients_gmail_yahoo = COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), "@gmail.com") | ENDSWITH(LOWER(email), "@yahoo.com")
        )
    )
)

