    (LOWER(diagnosis.diag_name) == 'psoriasis vulgaris') & (LOWER(drug.drug_type) == 'biologic')
)
result = DermTreatment.CALCULATE(
    patient_count=NDISTINCT(matching_treatments.patient_id)
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(
            LOWER(first_name) == LOWER("Alice")
        ).treatments_received.WHERE(
            (start_dt >= DATETIME("now", "start of month", "-6 months")) &
            (start_dt < DATETIME("now", "start of month"))
        )
    )
)

result = Drugs.WHERE(
    LOWER(drug_name) == LOWER('Drugalin')
).CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

result = DermTreatment.CALCULATE(
    avg_weight=AVG(Drugs.WHERE(LOWER(drug_name) == 'drugalin').treatments_used_in.patient.weight_kg)
)

result = DermTreatment.CALCULATE(
    caw_male = AVG(Patients.WHERE(LOWER(gender) == "male").weight_kg)
)

cohort_avg_weight = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

result = DermTreatment.CALCULATE(
    pic_female = COUNT(Patients.WHERE(
        (LOWER(gender) == 'female') & 
        (LOWER(ins_type) == 'private')
    ))
)

result = DermTreatment.CALCULATE(
    pic=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == "biologic")) == 1
).PARTITION(name="states", by=loc_state).CALCULATE(
    state=loc_state
)

biologic_doctor_states = DermTreatment.Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

result = Drugs.WHERE(
    HASNOT(treatments_used_in) == 1
).CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name
)

top_diagnoses = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diag_name=diag_name,
    num_patients=NDISTINCT(treatments_for.patient.patient_id),
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas)
).TOP_K(
    3,
    by=(max_itch_score.DESC(), num_patients.DESC())
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            LIKE(LOWER(diagnosis.diag_name), '%psoriasis%') &
            PRESENT(drug.fda_appr_dt) &
            (DATEDIFF("days", end_dt, DATETIME('now')) <= 180)
        )
    )
)

doctors_first_treatment = DermTreatment.Doctors.WHERE(
    year_reg == (YEAR(DATETIME('now')) - 2)
).prescribed_treatments.WHERE(
    RANKING(by=start_dt.ASC(), per="Doctors") == 1
).CALCULATE(
    doctor_last_name=last_name,
    registration_year=year_reg,
    first_treatment_id=treatment_id,
    first_treatment_date=start_dt
)

result = Treatments.WHERE(
    HAS(adverse_events) == 1
).adverse_events.WHERE(
    DATEDIFF("days", treatment.start_dt, reported_dt) <= 10
).CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_date=treatment.start_dt,
    adverse_event_date=reported_dt,
    adverse_event_description=description
)

result = Treatments.WHERE(
    is_placebo == True
).WHERE(
    HAS(concomitant_meds.WHERE(
        DATEDIFF("days", treatment.start_dt, start_dt) <= 14
    )) == 1
).CALCULATE(
    treatment_id,
    treatment_start_dt=start_dt,
    treatment_end_dt=end_dt,
    concomitant_med_start_dates=concomitant_meds.CALCULATE(
        start_date=start_dt
    ).start_date,
    concomitant_med_end_dates=concomitant_meds.CALCULATE(
        end_date=end_dt
    ).end_date
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

# First, create a collection of male patients with private insurance and calculate their current age in years.
male_private_patients_with_age = DermTreatment.Patients.WHERE(
    (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
).CALCULATE(
    age=DATEDIFF("years", date_of_birth, 'now')
)

# Next, calculate the average of the ages from the collection above and round it to the nearest integer.
result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(male_private_patients_with_age.age), 0)
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_durations = UserSessions.WHERE(
    (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
).CALCULATE(
    user_id=user_id,
    session_duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_user", by=(user_id,)
).CALCULATE(
    user_id=user_id,
    total_duration=SUM(UserSessions.session_duration)
).ORDER_BY(total_duration.DESC())

result = Ewallet.CALCULATE(
    total_count=COUNT(UserSessions.WHERE(
        DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
    ))
)

unread_promotional_notifications = Users.notifications.WHERE(
    (notification_type == 'promotional') & (status == 'unread')
)
us_users_with_unread_promos = Users.WHERE(
    (LOWER(country) == 'us') & (HAS(unread_promotional_notifications) == 1)
).CALCULATE(
    username=username,
    total_unread_promotional_notifications=COUNT(unread_promotional_notifications)
)

result = Transactions.WHERE(
    receiver_type == 1
).PARTITION(
    name="merchant_receivers", 
    by=receiver_id
).CALCULATE(
    merchant_id=receiver_id
)

distinct_merchant_receivers = Ewallet.Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=receiver_id).CALCULATE(
    merchant_id=receiver_id
)

result = Users.WHERE(
    HAS(notifications.WHERE(CONTAINS(LOWER(notification_type), "transaction"))) == 1
).CALCULATE(
    user_id=uid
)

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

active_retail_merchants_balances_today = Ewallet.Merchants.WHERE(
    (LOWER(status) == 'active') & CONTAINS(LOWER(category), 'retail')
).balances.WHERE(
    updated_at >= DATETIME('now', 'start of day')
)

median_balance_result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(active_retail_merchants_balances_today.balance)
)

# Find the earliest snapshot date in 2023
earliest_2023_snapshot = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).TOP_K(1, by=snapshot_date.ASC())

# Calculate the average limits for that earliest date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_monthly
    )
)

merchants_with_early_coupons = Ewallet.Merchants.WHERE(
    HAS(coupons) == 1
).CALCULATE(
    earliest_coupon_info=coupons.TOP_K(1, by=start_date.ASC()).SINGULAR()
).CALCULATE(
    merchant_id=mid,
    registration_date=created_at,
    earliest_coupon_id=earliest_coupon_info.cid,
    earliest_coupon_start_date=earliest_coupon_info.start_date
).WHERE(
    DATEDIFF("days", registration_date, earliest_coupon_start_date) <= 365
)

result = Users.WHERE(
    HASNOT(notifications.WHERE(
        (created_at >= Users.created_at) & 
        (created_at <= DATETIME(Users.created_at, '+1 year'))
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)

users_without_first_year_notification = Users.CALCULATE(
    signup_date=created_at,
    one_year_anniversary=DATETIME(created_at, '+1 year')
).WHERE(
    HASNOT(notifications.WHERE(
        (created_at >= signup_date) & (created_at < one_year_anniversary)
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=signup_date
)
